mapper.select:
SELECT r.`id` AS `id`, r.`item_id` AS `itemId`, r.`shop_id` AS `shopId`, r.`user_email` AS `userEmail`, r.`reservation_id` AS `reservationId`, r.`content` AS `content`, r.`rating` AS `rating`, r.`useful_count` AS `usefulCount`, r.`created_at` AS `createdAt`, r.`updated_at` AS `updatedAt`, u.`name` AS `userName` FROM `cors`.`item_reviews` AS r LEFT JOIN `cors`.`users` AS u ON r.`user_email` = u.`email` WHERE r.`item_id` = #{itemId}
ORDER BY r.`useful_count` DESC, r.`created_at` DESC
ORDER BY r.`created_at` DESC

SELECT COUNT(*)
FROM `cors`.`item_reviews`
WHERE `user_email` = #{email}
  AND `item_id` = #{itemId}
LIMIT 1
